notes=json.loads((ROOT/'evidence/01/notes.json').read_text('utf-8'))
def app(id,k,text):
    if text not in notes[id].get(k,''):notes[id][k]=notes[id].get(k,'')+'\n\n'+text
def add(id,path,locator,finding,repo_id=None):
    c=dict(path=path,locator=locator,finding=finding)
    if repo_id:
        m=json.loads((ROOT/'repositories/01'/repo_id/'source.json').read_text('utf-8'))
        c.update(repo_url=m['repo_url'],commit=m['commit'])
    if c not in notes[id].setdefault('code',[]):notes[id]['code'].append(c)

